SELECT CAST(json_object('automationId',a.automation_id,'state',a.state,'revision',a.revision,'definitionJson',a.definition_json,'anchorAtMs',a.anchor_at_ms,'createdAtMs',a.created_at_ms,'updatedAtMs',a.updated_at_ms,'executionMode',a.execution_mode,'importedContinuityJson',a.imported_continuity_json,'faultJson',a.fault_json,'faultedAtMs',a.faulted_at_ms,'nextDueMs',t.next_due_ms,'expiresAtMs',t.expires_at_ms,'admittedThroughMs',t.admitted_through_ms,'occupyingFiringId',t.occupying_firing_id,'waitingFiringId',t.waiting_firing_id,'externalRunId',t.occupying_external_run,'batches',json((SELECT json_group_array(json_object('batchId',b.batch_id,'serviceId',b.service_id,'digest',b.digest,'frozenBytes',b.frozen_bytes,'ackedAtMs',b.acked_at_ms)) FROM (SELECT * FROM automation_batches ORDER BY batch_id) b)),'firings',json((SELECT json_group_array(json_object('firingId',f.firing_id,'dueMs',f.due_ms,'foldedThroughMs',f.folded_through_ms,'pendingEntryJson',f.pending_entry_json,'state',f.state,'batchId',f.batch_id,'reportSeq',f.report_seq,'reportServiceId',f.report_service_id)) FROM automation_firings f WHERE f.automation_id=a.automation_id))) AS TEXT) AS observation FROM automations a JOIN automation_timing t USING(automation_id) WHERE a.automation_id=?;
